// ---------------------------------------------------------------------------
// DETERMINISTIC NODE - Priority Scorer + record consolidation
// Pure rules, no AI. Same logic as /priority_scorer.js in the repo.
// Reads the form + the two AI nodes, applies safe defaults if AI failed,
// computes a 0-100 priority score, and emits ONE clean ticket record that
// every downstream node reads from.
// ---------------------------------------------------------------------------

// --- 1. Gather inputs (with fallbacks so a failed AI call never breaks us) ---
const form = $('Support Ticket Form').item.json;

const clf = ($('Classifier (AI)').item.json && $('Classifier (AI)').item.json.output) || {};
const ext = ($('Extractor (AI)').item.json && $('Extractor (AI)').item.json.output) || {};

const customer_name = form['Customer Name'] || 'Customer';
const customer_email = form['Customer Email'] || '';
const message = form['Ticket Message'] || '';

// --- 2. Normalise AI output to known enums (defensive defaults) -------------
const ALLOWED_CATEGORIES = ['Billing', 'Technical', 'Account', 'General'];
const ALLOWED_SENTIMENT = ['positive', 'neutral', 'negative'];

let category = String(clf.category || 'General').trim();
category = ALLOWED_CATEGORIES.find(c => c.toLowerCase() === category.toLowerCase()) || 'General';

let sentiment = String(clf.sentiment || 'neutral').trim().toLowerCase();
if (!ALLOWED_SENTIMENT.includes(sentiment)) sentiment = 'neutral';

const summary = ext.summary || 'No summary available.';
const issue_keywords = Array.isArray(ext.issue_keywords) ? ext.issue_keywords : [];
const customer_intent = ext.customer_intent || 'Not specified.';

// --- 3. Deterministic priority score ---------------------------------------
const CATEGORY_WEIGHT = { Billing: 30, Technical: 30, Account: 20, General: 10 };
const SENTIMENT_BOOST = { negative: 25, neutral: 5, positive: 0 };
const URGENCY_KEYWORDS = ['urgent','asap','immediately','down','outage','broken','refund','cancel','charged','unauthorized','not working','can\'t log','cannot log','error','failed','escalate'];

const text = (message + ' ' + issue_keywords.join(' ')).toLowerCase();
let urgencyHits = 0;
for (const kw of URGENCY_KEYWORDS) { if (text.includes(kw)) urgencyHits++; }
const urgencyScore = Math.min(urgencyHits * 8, 40); // cap urgency contribution

let priority_score = (CATEGORY_WEIGHT[category] || 10) + (SENTIMENT_BOOST[sentiment] || 0) + urgencyScore;
priority_score = Math.max(0, Math.min(100, priority_score));

let priority_level = 'Low';
if (priority_score >= 70) priority_level = 'High';
else if (priority_score >= 40) priority_level = 'Medium';

// --- 4. Deterministic team routing map (canonical source of truth) ----------
const TEAM_MAP = {
  Billing:   { team_label: 'Billing Team',  team_email: 'billing@company.example' },
  Technical: { team_label: 'Tech Team',     team_email: 'tech@company.example' },
  Account:   { team_label: 'Account Team',  team_email: 'accounts@company.example' },
  General:   { team_label: 'General Queue',  team_email: 'support@company.example' }
};
const team = TEAM_MAP[category];

// --- 5. Emit ONE consolidated ticket record --------------------------------
const ticket_id = 'TKT-' + Date.now();

return {
  json: {
    ticket_id,
    customer_name,
    customer_email,
    message,
    product_area: form['Product Area'] || 'Other',
    category,
    sentiment,
    summary,
    issue_keywords,
    customer_intent,
    urgency_hits: urgencyHits,
    priority_score,
    priority_level,
    team_label: team.team_label,
    team_email: team.team_email,
    received_at: new Date().toISOString()
  }
};

